import React, { useState, useEffect } from "react";

function Header() {
    const [nextEvent, setNextEvent] = useState(null);
    const [timeLeft, setTimeLeft] = useState({ d: 0, h: 0, m: 0, s: 0, isLive: false });

    // 1. Fetch from your events API
    useEffect(() => {
        fetch("http://localhost:8000/api/events/upcoming")
            .then(res => res.json())
            .then(res => {
                if (res.data && res.data.length > 0) {
                    setNextEvent(res.data[0]);
                }
            })
            .catch(err => console.error("Error loading events:", err));
    }, []);

    // 2. Precise Countdown Logic
    useEffect(() => {
        if (!nextEvent) return;

        const timer = setInterval(() => {
            const now = new Date().getTime();
            const start = new Date(nextEvent.start_date).getTime();
            const end = new Date(nextEvent.end_date).getTime();
            const gap = start - now;

            if (now >= start && now <= end) {
                setTimeLeft(prev => ({ ...prev, isLive: true }));
                return;
            }

            if (gap > 0) {
                setTimeLeft({
                    d: Math.floor(gap / (1000 * 60 * 60 * 24)),
                    h: Math.floor((gap % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
                    m: Math.floor((gap % (1000 * 60 * 60)) / (1000 * 60)),
                    s: Math.floor((gap % (1000 * 60)) / 1000),
                    isLive: false
                });
            }
        }, 1000);

        return () => clearInterval(timer);
    }, [nextEvent]);

    // --- STYLES ---
    const headerWrapper = {
        background: "#a82324",
        padding: "40px 20px 60px 20px",
        borderBottomLeftRadius: "40px",
        borderBottomRightRadius: "40px",
        color: "white",
        boxShadow: "0 10px 30px rgba(168,35,36,0.3)"
    };

    const heroCard = {
        background: "rgba(255, 255, 255, 0.1)",
        padding: "25px",
        borderRadius: "30px",
        backdropFilter: "blur(10px)",
        border: "1px solid rgba(255, 255, 255, 0.2)"
    };

    const timeBoxStyle = { display: "flex", justifyContent: "center", gap: "12px", margin: "20px 0" };

    const unitStyle = {
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        background: "rgba(255,255,255,0.2)",
        padding: "10px",
        borderRadius: "15px",
        minWidth: "55px"
    };

    return (
        <header style={headerWrapper}>
            <div style={heroCard}>
                {!nextEvent ? (
                    <div style={{ textAlign: "center", opacity: 0.8 }}>Searching for upcoming events...</div>
                ) : (
                    <>
                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                            <div style={{ background: "white", color: "#a82324", padding: "4px 12px", borderRadius: "20px", fontSize: "0.7rem", fontWeight: "bold" }}>
                                {timeLeft.isLive ? "● LIVE NOW" : "NEXT EVENT"}
                            </div>
                            <span className="material-icons-round" style={{ fontSize: "20px" }}>notifications</span>
                        </div>

                        <div style={timeBoxStyle}>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.4rem", fontWeight: "bold" }}>{timeLeft.d}</span>
                                <span style={{ fontSize: "0.5rem", opacity: 0.8 }}>DAYS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.4rem", fontWeight: "bold" }}>{timeLeft.h}</span>
                                <span style={{ fontSize: "0.5rem", opacity: 0.8 }}>HRS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.4rem", fontWeight: "bold" }}>{timeLeft.m}</span>
                                <span style={{ fontSize: "0.5rem", opacity: 0.8 }}>MINS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.4rem", fontWeight: "bold" }}>{timeLeft.s}</span>
                                <span style={{ fontSize: "0.5rem", opacity: 0.8 }}>SECS</span>
                            </div>
                        </div>

                        <h2 style={{ margin: "10px 0 5px 0", fontSize: "1.4rem", fontWeight: "600", textAlign: "center" }}>
                            {nextEvent.name}
                        </h2>
                        <p style={{ margin: 0, opacity: 0.8, fontSize: "0.8rem", textAlign: "center" }}>
                            <span className="material-icons-round" style={{ fontSize: "12px", marginRight: "4px" }}>place</span>
                            {nextEvent.venue_details || "Venue to be announced"}
                        </p>
                    </>
                )}
            </div>
        </header>
    );
}

export default Header;
